      const p0 = Kp[Math.max(0, i - 1)], p1 = Kp[i], p2 = Kp[i + 1], p3 = Kp[Math.min(Kp.length - 1, i + 2)];
      const n = Math.max(1, Math.ceil(Math.hypot(p2[0] - p1[0], p2[1] - p1[1]) / 1.0));
