    // мелкие помощники
    const qv = (bk, F, pts, col, s) => bk.quad(F.p(...pts[0]), F.p(...pts[1]), F.p(...pts[2]), F.p(...pts[3]), col, s);
    const vgrad = (c, y0, y1, k0 = 0.8) => p => mul(c, lerp(k0, 1, clamp((p[1] - y0) / (y1 - y0), 0, 1)));
