      const ruv = (pts, ex, ez) => pts.map(p => { const w = F.p(...p), e = F.dir(ex, ez); return [(w[0] * e[0] + w[2] * e[1]) / 2.0, (w[0] * -e[1] + w[2] * e[0]) / 0.5 + w[1] * 1.5]; });
