      let n = G1 ? g.bays : Math.floor((W - 0.6) / 0.75); n = Math.max(2, Math.min(n, Math.floor((W - 0.3) / bw)));
      const gw = n * bw, x0 = -gw / 2, yb = s * ST + 0.12, ap = G1 ? 0.75 : 0.7, gh = G1 ? 1.35 : 1.5, top = yb + ap + gh;
