        { const [ox, oz] = pts(rOut, (a0 + a1) / 2); camExtra.push({ type: 'box', x: ox, z: oz, w: rOut * (a1 - a0) + 0.05, d: 0.4, ry: -(a0 + a1) / 2, y0: y0 - 0.5, y1: yt + 0.3, id: 'metroWall', cam: true }); }
