      { const a = 75 * D2, r = rInner(0) - 0.012, F = new K.Frame(TXc + Math.sin(a) * r, y0, TZc + Math.cos(a) * r, a + PI); bk.quad(F.p(-0.45, 0, 0), F.p(0.45, 0, 0), F.p(0.45, 1.75, 0), F.p(-0.45, 1.75, 0), rgb('#F2E8D2'), S.FLAT); }
