      const i = lo, fi = clamp((rho - Rr[i]) / (Rr[i + 1] - Rr[i]), 0, 1), aj = a / TAU * BG.NA, j = Math.min(BG.NA - 1, Math.floor(aj)), fj = aj - j, N1 = BG.NA + 1, Y = BG.gridY;
